do $seed$
declare
  d jsonb := $j${"fieldsets":{"order":[["order_ref","Order reference","text","Marketplace / store order id"],["channel","Channel","text","Channel name, e.g. Amazon India"],["channel_type","Channel type","text","d2c or marketplace"],["payment_type","Payment type","text","prepaid or cod"],["ship_state","Ship-to state","text","Place of supply"],["interstate","Interstate supply","boolean","true when ship-to state differs from company state (IGST)"],["amount","Invoice total","number","GST-inclusive invoice value"],["taxable","Taxable value","number","Invoice total minus GST"],["tax","GST amount","number","Total GST on the invoice"],["cgst","CGST","number","Half of GST for intrastate supplies, else 0"],["sgst","SGST","number","Half of GST for intrastate supplies, else 0"],["igst","IGST","number","Full GST for interstate supplies, else 0"],["has_invoice","Order was invoiced","boolean","false means there is nothing to reverse"],["already_credited","Credit note already exists","boolean","prevents double reversal"]],"inv":[["movement_type","Movement type","text",""],["sku","SKU","text",""],["product","Product","text",""],["warehouse","Warehouse","text",""],["quantity","Quantity (signed)","number","negative = stock going out"],["qty","Quantity (absolute)","number","always positive"],["unit_cost","Unit cost price","number",""],["cogs","Cost value","number","absolute quantity x unit cost"]],"bank":[["description","Bank narration","text","The reference / narration on the bank statement line"],["amount","Amount","number","GST-inclusive amount of the bank line"],["direction","Direction","text","debit (money out) or credit (money in)"],["bank_account","Bank","text","Bank name"],["base","Amount before GST","number","Filled using the rule's GST rate"],["tax","GST in the amount","number","Filled using the rule's GST rate"]]},"events":[{"code":"return.accepted","label":"Customer return accepted","desc":"Goods came back from the customer (reverse pickup received). Revenue and GST are reversed with a credit note.","trig":"Return status becomes Received / Inspected / Restocked / Quarantined / Claimed","src":"return","pack":"core","sample":{"order_ref":"SHOP-1101","channel":"Shopify Store","channel_type":"d2c","payment_type":"prepaid","ship_state":"Gujarat","interstate":false,"amount":1049.0,"taxable":999.05,"tax":49.95,"cgst":24.98,"sgst":24.97,"igst":0,"has_invoice":true,"already_credited":false,"reason":"Size/fit issue","date":"2026-10-04"},"order":10,"fs":"order","extra":[["reason","Return reason","text","e.g. Size/fit issue, Damaged on arrival, Wrong item"]]},{"code":"return.refund_paid","label":"Customer refund paid","desc":"The refund has been paid to the customer (return refund status = Refunded).","trig":"Return refund status becomes Refunded","src":"return","pack":"core","sample":{"order_ref":"SHOP-1101","channel":"Shopify Store","channel_type":"d2c","payment_type":"prepaid","ship_state":"Gujarat","interstate":false,"amount":1049.0,"taxable":999.05,"tax":49.95,"cgst":24.98,"sgst":24.97,"igst":0,"has_invoice":true,"already_credited":false,"reason":"Size/fit issue","date":"2026-10-04"},"order":20,"fs":"order","extra":[["reason","Return reason","text",""]]},{"code":"return.writeoff","label":"Returned goods not resaleable","desc":"Returned goods were quarantined or claimed - cost is moved out of COGS into losses.","trig":"Return status becomes Quarantined or Claimed","src":"return","pack":"inventory_cogs","sample":{"order_ref":"SHOP-1101","channel":"Shopify Store","channel_type":"d2c","payment_type":"prepaid","ship_state":"Gujarat","interstate":false,"amount":1049.0,"taxable":999.05,"tax":49.95,"cgst":24.98,"sgst":24.97,"igst":0,"has_invoice":true,"already_credited":false,"reason":"Damaged on arrival","inspection_result":"damaged","disposition":"claimed","cogs":640.0,"date":"2026-10-04"},"order":30,"fs":"order","extra":[["reason","Return reason","text",""],["inspection_result","Inspection result","text","good / damaged / wrong_item / missing"],["disposition","Disposition","text","quarantined or claimed"],["cogs","Cost of goods","number","Quantity x cost price of the order lines"]]},{"code":"order.cancelled","label":"Invoiced order cancelled","desc":"An order that was already invoiced is cancelled before delivery - the invoice is reversed.","trig":"Order fulfilment status becomes Cancelled and an invoice exists","src":"order","pack":"core","sample":{"order_ref":"SHOP-1101","channel":"Shopify Store","channel_type":"d2c","payment_type":"prepaid","ship_state":"Gujarat","interstate":false,"amount":1049.0,"taxable":999.05,"tax":49.95,"cgst":24.98,"sgst":24.97,"igst":0,"has_invoice":true,"already_credited":false,"date":"2026-10-04"},"order":40,"fs":"order","extra":[]},{"code":"rto.received","label":"RTO received at warehouse","desc":"A shipment that could not be delivered is back at the warehouse. The sale is reversed with a credit note.","trig":"RTO status becomes Received / Inspected / Restocked / Quarantined / Claimed","src":"rto","pack":"core","sample":{"order_ref":"SHOP-1101","channel":"Shopify Store","channel_type":"d2c","payment_type":"cod","ship_state":"Gujarat","interstate":false,"amount":1049.0,"taxable":999.05,"tax":49.95,"cgst":24.98,"sgst":24.97,"igst":0,"has_invoice":true,"already_credited":false,"reason":"Customer unreachable","awb":"AWB1234567890","date":"2026-10-04"},"order":50,"fs":"order","extra":[["reason","RTO reason","text","e.g. Customer unreachable, Address incomplete, Refused"],["awb","AWB","text","Courier waybill"]]},{"code":"rto.writeoff","label":"RTO goods not resaleable","desc":"RTO goods came back damaged / swapped / incomplete - cost is moved out of COGS into losses.","trig":"RTO status becomes Quarantined or Claimed","src":"rto","pack":"inventory_cogs","sample":{"order_ref":"SHOP-1101","channel":"Shopify Store","channel_type":"d2c","payment_type":"prepaid","ship_state":"Gujarat","interstate":false,"amount":1049.0,"taxable":999.05,"tax":49.95,"cgst":24.98,"sgst":24.97,"igst":0,"has_invoice":true,"already_credited":false,"reason":"Customer refused","inspection_result":"damaged","disposition":"quarantined","cogs":640.0,"date":"2026-10-04"},"order":60,"fs":"order","extra":[["reason","RTO reason","text",""],["awb","AWB","text",""],["inspection_result","Inspection result","text",""],["disposition","Disposition","text",""],["cogs","Cost of goods","number",""]]},{"code":"cod.collected","label":"COD cash collected by courier","desc":"The courier collected cash from the customer. The money now sits with the courier, not with the customer.","trig":"COD collected amount increases","src":"cod","pack":"core","sample":{"courier":"Delhivery","order_ref":"SHOP-1105","amount":1299.0,"cod_amount":1299.0,"date":"2026-10-04"},"order":70,"fs":null,"extra":[["courier","Courier","text","Courier name"],["order_ref","Order reference","text",""],["amount","Amount collected now","number",""],["cod_amount","COD order value","number",""]]},{"code":"cod.remitted","label":"COD remittance received","desc":"The courier remitted COD cash to the bank.","trig":"COD remitted amount increases","src":"cod","pack":"core","sample":{"courier":"Delhivery","order_ref":"SHOP-1105","amount":1299.0,"total_remitted":1299.0,"cod_amount":1299.0,"short":0,"date":"2026-10-04"},"order":80,"fs":null,"extra":[["courier","Courier","text",""],["order_ref","Order reference","text",""],["amount","Amount remitted now","number",""],["total_remitted","Total remitted so far","number",""],["cod_amount","COD order value","number",""],["short","Still short","number","COD value minus total remitted"]]},{"code":"settlement.reconciled","label":"Marketplace settlement reconciled","desc":"A marketplace / gateway payout has been matched to the bank. Money received, shortfall or excess recognised.","trig":"Settlement status moves from Pending to Reconciled / Short pay / Excess","src":"settlement","pack":"core","sample":{"channel":"Amazon India","channel_type":"marketplace","settlement_ref":"AMZ-SETTLE-2026-09-S1","gross":52000.0,"deductions":8120.0,"expected":43880.0,"actual":43740.0,"short":140.0,"excess":0,"date":"2026-10-04"},"order":90,"fs":null,"extra":[["channel","Channel","text",""],["channel_type","Channel type","text",""],["settlement_ref","Settlement id","text",""],["gross","Gross sales in settlement","number",""],["deductions","Fees deducted (incl. GST)","number",""],["expected","Expected payout","number","gross minus deductions"],["actual","Actual payout received","number",""],["short","Short-paid","number","expected minus actual, if positive"],["excess","Excess received","number","actual minus expected, if positive"]]},{"code":"claim.approved","label":"Claim approved","desc":"A courier / marketplace claim was approved. The recovery is now virtually certain, so it is recognised.","trig":"Claim status becomes Approved","src":"claim","pack":"core","sample":{"claim_type":"lost_shipment","order_ref":"AMAZ-1114","amount":1099.0,"channel":"Amazon India","date":"2026-10-04"},"order":100,"fs":null,"extra":[["claim_type","Claim type","text","lost_shipment / damaged_return / incorrect_deduction / excess_deduction / other"],["order_ref","Order reference","text",""],["amount","Approved amount","number",""],["channel","Channel","text",""]]},{"code":"claim.recovered","label":"Claim amount recovered","desc":"Money for an approved claim was received.","trig":"Claim recovered amount increases","src":"claim","pack":"core","sample":{"claim_type":"lost_shipment","order_ref":"AMAZ-1114","amount":1099.0,"total_recovered":1099.0,"date":"2026-10-04"},"order":110,"fs":null,"extra":[["claim_type","Claim type","text",""],["order_ref","Order reference","text",""],["amount","Amount recovered now","number",""],["total_recovered","Total recovered so far","number",""]]},{"code":"claim.rejected","label":"Claim rejected","desc":"A claim was rejected. Nothing was recognised on filing, so by default there is no entry.","trig":"Claim status becomes Rejected","src":"claim","pack":"core","sample":{"claim_type":"damaged_return","order_ref":"FLIP-1106","amount":799.0,"date":"2026-10-04"},"order":120,"fs":null,"extra":[["claim_type","Claim type","text",""],["order_ref","Order reference","text",""],["amount","Claimed amount","number",""]]},{"code":"inventory.sale_dispatch","label":"Stock dispatched for a sale","desc":"Perpetual-inventory entry for a stock movement.","trig":"A stock movement of type sale_dispatch is recorded","src":"inventory","pack":"inventory_cogs","sample":{"movement_type":"sale_dispatch","sku":"MTEE-BLK-M","product":"Men Round Neck Cotton T-Shirt - Black","warehouse":"Surat Warehouse","quantity":-1,"qty":1,"unit_cost":160.0,"cogs":160.0,"date":"2026-10-04"},"order":200,"fs":"inv","extra":[]},{"code":"inventory.return_restock","label":"Stock restocked from a return","desc":"Perpetual-inventory entry for a stock movement.","trig":"A stock movement of type return_restock is recorded","src":"inventory","pack":"inventory_cogs","sample":{"movement_type":"return_restock","sku":"MTEE-BLK-M","product":"Men Round Neck Cotton T-Shirt - Black","warehouse":"Surat Warehouse","quantity":-1,"qty":1,"unit_cost":160.0,"cogs":160.0,"date":"2026-10-04"},"order":200,"fs":"inv","extra":[]},{"code":"inventory.rto_restock","label":"Stock restocked from an RTO","desc":"Perpetual-inventory entry for a stock movement.","trig":"A stock movement of type rto_restock is recorded","src":"inventory","pack":"inventory_cogs","sample":{"movement_type":"rto_restock","sku":"MTEE-BLK-M","product":"Men Round Neck Cotton T-Shirt - Black","warehouse":"Surat Warehouse","quantity":-1,"qty":1,"unit_cost":160.0,"cogs":160.0,"date":"2026-10-04"},"order":200,"fs":"inv","extra":[]},{"code":"inventory.adjustment","label":"Stock adjustment (count difference, damage, found stock)","desc":"Perpetual-inventory entry for a stock movement.","trig":"A stock movement of type adjustment is recorded","src":"inventory","pack":"inventory_cogs","sample":{"movement_type":"adjustment","sku":"MTEE-BLK-M","product":"Men Round Neck Cotton T-Shirt - Black","warehouse":"Surat Warehouse","quantity":-1,"qty":1,"unit_cost":160.0,"cogs":160.0,"date":"2026-10-04"},"order":200,"fs":"inv","extra":[]},{"code":"inventory.initial_stock","label":"Opening stock loaded","desc":"Perpetual-inventory entry for a stock movement.","trig":"A stock movement of type initial_stock is recorded","src":"inventory","pack":"inventory_cogs","sample":{"movement_type":"initial_stock","sku":"MTEE-BLK-M","product":"Men Round Neck Cotton T-Shirt - Black","warehouse":"Surat Warehouse","quantity":-1,"qty":1,"unit_cost":160.0,"cogs":160.0,"date":"2026-10-04"},"order":200,"fs":"inv","extra":[]},{"code":"bank.debit","label":"Bank statement line - money out","desc":"QuickBooks-style bank rule: classify a payment by keywords in the bank narration.","trig":"A bank line (debit) is imported or added and is still unmatched","src":"bank_txn","pack":"core","sample":{"description":"DELHIVERY FREIGHT INV 5521","amount":4260.0,"direction":"debit","bank_account":"HDFC Bank","date":"2026-10-04"},"order":300,"fs":"bank","extra":[]},{"code":"bank.credit","label":"Bank statement line - money in","desc":"Classify a receipt by keywords in the bank narration.","trig":"A bank line (credit) is imported or added and is still unmatched","src":"bank_txn","pack":"core","sample":{"description":"UPI-CR-7734209981","amount":1250.0,"direction":"credit","bank_account":"HDFC Bank","date":"2026-10-04"},"order":310,"fs":"bank","extra":[]}],"rules":[{"code":"RET-CN-MKT","name":"Return accepted - marketplace order (credit note)","notes":"On a marketplace sale the platform collects the money and refunds the customer itself, then adjusts our next settlement. So we reverse revenue and GST and reduce what the marketplace owes us (Trade Receivables). No cash leaves our bank.","group":"Customer returns","pack":"core","event":"return.accepted","action":"post","vt":"CREDIT_NOTE","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Credit note - customer return {order_ref} ({reason}) - refund is netted in the {channel} settlement","active":true,"conds":[["has_invoice","equals","true"],["already_credited","equals","false"],["channel_type","equals","marketplace"]],"lines":[["debit","Sales Returns & RTO Reversals","taxable"],["debit","CGST Payable (Output)","cgst"],["debit","SGST Payable (Output)","sgst"],["debit","IGST Payable (Output)","igst"],["credit","Trade Receivables","amount"]]},{"code":"RET-CN-D2C","name":"Return accepted - own store order (credit note)","notes":"On our own store we already hold (or will hold) the customer's money. Reversing the sale creates a liability to refund the customer (Customer Refunds Payable), cleared when the refund is paid.","group":"Customer returns","pack":"core","event":"return.accepted","action":"post","vt":"CREDIT_NOTE","mode":"all","priority":20,"stop":true,"auto":true,"gst":null,"narr":"Credit note - customer return {order_ref} ({reason}) - refund due to customer","active":true,"conds":[["has_invoice","equals","true"],["already_credited","equals","false"],["channel_type","equals","d2c"]],"lines":[["debit","Sales Returns & RTO Reversals","taxable"],["debit","CGST Payable (Output)","cgst"],["debit","SGST Payable (Output)","sgst"],["debit","IGST Payable (Output)","igst"],["credit","Customer Refunds Payable","amount"]]},{"code":"RET-CN-OTHER","name":"Return accepted - any other channel (credit note)","notes":"Safety net so a return on a new channel type is never left without a credit note.","group":"Customer returns","pack":"core","event":"return.accepted","action":"post","vt":"CREDIT_NOTE","mode":"all","priority":90,"stop":true,"auto":true,"gst":null,"narr":"Credit note - customer return {order_ref} ({reason})","active":true,"conds":[["has_invoice","equals","true"],["already_credited","equals","false"]],"lines":[["debit","Sales Returns & RTO Reversals","taxable"],["debit","CGST Payable (Output)","cgst"],["debit","SGST Payable (Output)","sgst"],["debit","IGST Payable (Output)","igst"],["credit","Trade Receivables","amount"]]},{"code":"RET-REFUND-D2C","name":"Refund paid to customer - own store","notes":"Clears the refund liability raised when the credit note was issued.","group":"Customer returns","pack":"core","event":"return.refund_paid","action":"post","vt":"PAYMENT","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Refund paid to customer - return {order_ref}","active":true,"conds":[["channel_type","equals","d2c"]],"lines":[["debit","Customer Refunds Payable","amount"],["credit","BANK","amount"]]},{"code":"RET-REFUND-MKT","name":"Refund on marketplace order - leave to settlement","notes":"The marketplace refunds the customer and recovers it through the settlement. No bank entry in our books.","group":"Customer returns","pack":"core","event":"return.refund_paid","action":"ignore","vt":"JOURNAL","mode":"all","priority":20,"stop":true,"auto":true,"gst":null,"narr":null,"active":true,"conds":[["channel_type","equals","marketplace"]],"lines":[]},{"code":"ORD-CANCEL-D2C-PREPAID","name":"Invoiced order cancelled - own store, prepaid (credit note)","notes":null,"group":"Cancellations","pack":"core","event":"order.cancelled","action":"post","vt":"CREDIT_NOTE","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Credit note - order {order_ref} cancelled after invoicing - prepaid amount to be refunded","active":true,"conds":[["has_invoice","equals","true"],["already_credited","equals","false"],["channel_type","equals","d2c"],["payment_type","equals","prepaid"]],"lines":[["debit","Sales Returns & RTO Reversals","taxable"],["debit","CGST Payable (Output)","cgst"],["debit","SGST Payable (Output)","sgst"],["debit","IGST Payable (Output)","igst"],["credit","Customer Refunds Payable","amount"]]},{"code":"ORD-CANCEL-OTHER","name":"Invoiced order cancelled - everything else (credit note)","notes":"COD and marketplace orders: nothing was collected from the customer by us, so the receivable is reduced.","group":"Cancellations","pack":"core","event":"order.cancelled","action":"post","vt":"CREDIT_NOTE","mode":"all","priority":90,"stop":true,"auto":true,"gst":null,"narr":"Credit note - order {order_ref} cancelled after invoicing","active":true,"conds":[["has_invoice","equals","true"],["already_credited","equals","false"]],"lines":[["debit","Sales Returns & RTO Reversals","taxable"],["debit","CGST Payable (Output)","cgst"],["debit","SGST Payable (Output)","sgst"],["debit","IGST Payable (Output)","igst"],["credit","Trade Receivables","amount"]]},{"code":"RTO-REV-COD","name":"RTO received - COD order (credit note)","notes":"The parcel never reached the customer, so the sale did not happen. COD means no money was collected, so only the receivable is reversed.","group":"RTO / undelivered","pack":"core","event":"rto.received","action":"post","vt":"CREDIT_NOTE","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Credit note - RTO of order {order_ref} ({reason}), AWB {awb}","active":true,"conds":[["has_invoice","equals","true"],["already_credited","equals","false"],["payment_type","equals","cod"]],"lines":[["debit","Sales Returns & RTO Reversals","taxable"],["debit","CGST Payable (Output)","cgst"],["debit","SGST Payable (Output)","sgst"],["debit","IGST Payable (Output)","igst"],["credit","Trade Receivables","amount"]]},{"code":"RTO-REV-PREPAID-D2C","name":"RTO received - own store, prepaid (credit note)","notes":"Customer already paid us, so reversing the sale creates a refund liability.","group":"RTO / undelivered","pack":"core","event":"rto.received","action":"post","vt":"CREDIT_NOTE","mode":"all","priority":20,"stop":true,"auto":true,"gst":null,"narr":"Credit note - RTO of order {order_ref} ({reason}), AWB {awb} - prepaid amount to be refunded","active":true,"conds":[["has_invoice","equals","true"],["already_credited","equals","false"],["payment_type","equals","prepaid"],["channel_type","equals","d2c"]],"lines":[["debit","Sales Returns & RTO Reversals","taxable"],["debit","CGST Payable (Output)","cgst"],["debit","SGST Payable (Output)","sgst"],["debit","IGST Payable (Output)","igst"],["credit","Customer Refunds Payable","amount"]]},{"code":"RTO-REV-OTHER","name":"RTO received - marketplace / other (credit note)","notes":null,"group":"RTO / undelivered","pack":"core","event":"rto.received","action":"post","vt":"CREDIT_NOTE","mode":"all","priority":90,"stop":true,"auto":true,"gst":null,"narr":"Credit note - RTO of order {order_ref} ({reason}), AWB {awb}","active":true,"conds":[["has_invoice","equals","true"],["already_credited","equals","false"]],"lines":[["debit","Sales Returns & RTO Reversals","taxable"],["debit","CGST Payable (Output)","cgst"],["debit","SGST Payable (Output)","sgst"],["debit","IGST Payable (Output)","igst"],["credit","Trade Receivables","amount"]]},{"code":"COD-COLLECTED","name":"COD cash collected by courier","notes":"Moves the amount from 'customer owes us' to 'courier owes us'. Whatever the courier has not remitted stays visible here.","group":"Cash on delivery","pack":"core","event":"cod.collected","action":"post","vt":"JOURNAL","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"COD collected by {courier} for order {order_ref}","active":true,"conds":[],"lines":[["debit","COD Receivable from Couriers","amount"],["credit","Trade Receivables","amount"]]},{"code":"COD-REMITTED","name":"COD remittance received from courier","notes":null,"group":"Cash on delivery","pack":"core","event":"cod.remitted","action":"post","vt":"RECEIPT","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"COD remittance from {courier} for order {order_ref}","active":true,"conds":[],"lines":[["debit","BANK","amount"],["credit","COD Receivable from Couriers","amount"]]},{"code":"STL-RECEIPT","name":"Marketplace / gateway settlement received","notes":"Fees and ITC were already booked when the settlement was reconciled. This entry records the cash: the payout hits the bank, any short-payment becomes a receivable to chase, any excess becomes a liability.","group":"Settlements","pack":"core","event":"settlement.reconciled","action":"post","vt":"RECEIPT","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Settlement {settlement_ref} from {channel}","active":true,"conds":[],"lines":[["debit","BANK","actual"],["debit","Settlement Short-Pay Receivable","short"],["credit","Trade Receivables","expected"],["credit","Settlement Excess Received","excess"]]},{"code":"CLM-APPROVED-DEDUCTION","name":"Claim approved - wrongly deducted fee","notes":"A recovered over-deduction is not income - it reverses the expense that was wrongly booked.","group":"Claims","pack":"core","event":"claim.approved","action":"post","vt":"JOURNAL","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Claim approved - fee wrongly deducted, order {order_ref}","active":true,"conds":[["claim_type","in","incorrect_deduction|excess_deduction"]],"lines":[["debit","Claims Receivable - Courier & Marketplace","amount"],["credit","Marketplace Commission Expense","amount"]]},{"code":"CLM-APPROVED","name":"Claim approved - lost / damaged shipment","notes":"Recognised only on approval - a filed claim is a contingent asset and is not booked until recovery is virtually certain.","group":"Claims","pack":"core","event":"claim.approved","action":"post","vt":"JOURNAL","mode":"all","priority":20,"stop":true,"auto":true,"gst":null,"narr":"Claim approved ({claim_type}) - order {order_ref}","active":true,"conds":[],"lines":[["debit","Claims Receivable - Courier & Marketplace","amount"],["credit","Courier & Marketplace Claim Recoveries","amount"]]},{"code":"CLM-RECOVERED","name":"Claim amount received","notes":null,"group":"Claims","pack":"core","event":"claim.recovered","action":"post","vt":"RECEIPT","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Claim recovery received - order {order_ref}","active":true,"conds":[],"lines":[["debit","BANK","amount"],["credit","Claims Receivable - Courier & Marketplace","amount"]]},{"code":"INV-INITIAL","name":"Opening stock loaded","notes":"Stock brought in at go-live. Switch the whole 'Inventory & COGS' pack on only after posting an opening-stock valuation entry, otherwise the Inventory ledger starts negative.","group":"Inventory & COGS","pack":"inventory_cogs","event":"inventory.initial_stock","action":"post","vt":"JOURNAL","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Opening stock - {sku}","active":false,"conds":[],"lines":[["debit","Inventory - Stock-in-Trade","cogs"],["credit","Opening Balance Equity","cogs"]]},{"code":"INV-DISPATCH-COGS","name":"Stock dispatched - cost of goods sold","notes":"Cost moves from stock to COGS when goods leave the warehouse. Switch the whole 'Inventory & COGS' pack on only after posting an opening-stock valuation entry, otherwise the Inventory ledger starts negative.","group":"Inventory & COGS","pack":"inventory_cogs","event":"inventory.sale_dispatch","action":"post","vt":"JOURNAL","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"COGS - {sku} x {qty}","active":false,"conds":[],"lines":[["debit","Cost of Goods Sold","cogs"],["credit","Inventory - Stock-in-Trade","cogs"]]},{"code":"INV-RETURN-RESTOCK","name":"Returned stock back in warehouse","notes":"Resaleable returned goods go back into stock at cost and COGS is reversed.","group":"Inventory & COGS","pack":"inventory_cogs","event":"inventory.return_restock","action":"post","vt":"JOURNAL","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Return restock - {sku} x {qty}","active":false,"conds":[],"lines":[["debit","Inventory - Stock-in-Trade","cogs"],["credit","Cost of Goods Sold","cogs"]]},{"code":"INV-RTO-RESTOCK","name":"RTO stock back in warehouse","notes":null,"group":"Inventory & COGS","pack":"inventory_cogs","event":"inventory.rto_restock","action":"post","vt":"JOURNAL","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"RTO restock - {sku} x {qty}","active":false,"conds":[],"lines":[["debit","Inventory - Stock-in-Trade","cogs"],["credit","Cost of Goods Sold","cogs"]]},{"code":"INV-ADJ-LOSS","name":"Stock adjustment - shortage / damage","notes":"Counted short or damaged in the warehouse. Under GST Sec 17(5)(h) ITC on goods lost, stolen or destroyed must be reversed - your CA can add that as an extra line.","group":"Inventory & COGS","pack":"inventory_cogs","event":"inventory.adjustment","action":"post","vt":"JOURNAL","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Stock shortage / damage - {sku} x {qty}","active":false,"conds":[["quantity","lt","0"]],"lines":[["debit","Damaged & Lost Stock Loss","cogs"],["credit","Inventory - Stock-in-Trade","cogs"]]},{"code":"INV-ADJ-GAIN","name":"Stock adjustment - excess found","notes":null,"group":"Inventory & COGS","pack":"inventory_cogs","event":"inventory.adjustment","action":"post","vt":"JOURNAL","mode":"all","priority":20,"stop":true,"auto":true,"gst":null,"narr":"Stock excess found - {sku} x {qty}","active":false,"conds":[["quantity","gt","0"]],"lines":[["debit","Inventory - Stock-in-Trade","cogs"],["credit","Damaged & Lost Stock Loss","cogs"]]},{"code":"INV-WRITEOFF-RETURN","name":"Returned goods not resaleable - move cost to loss","notes":"Goods that will not be resold are a loss, not COGS. Quarantined stock is NOT written off by default (it may be resold as B-grade); change the condition if your policy differs.","group":"Inventory & COGS","pack":"inventory_cogs","event":"return.writeoff","action":"post","vt":"JOURNAL","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Returned goods written off - {order_ref} ({inspection_result})","active":false,"conds":[["disposition","equals","claimed"]],"lines":[["debit","Damaged & Lost Stock Loss","cogs"],["credit","Cost of Goods Sold","cogs"]]},{"code":"INV-WRITEOFF-RTO","name":"RTO goods not resaleable - move cost to loss","notes":null,"group":"Inventory & COGS","pack":"inventory_cogs","event":"rto.writeoff","action":"post","vt":"JOURNAL","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"RTO goods written off - {order_ref} ({inspection_result})","active":false,"conds":[["disposition","equals","claimed"]],"lines":[["debit","Damaged & Lost Stock Loss","cogs"],["credit","Cost of Goods Sold","cogs"]]},{"code":"BNK-RTO-CHARGES","name":"RTO / reverse pickup charges","notes":"Kept separate from forward freight so you can see what returns really cost you.","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":5,"stop":true,"auto":true,"gst":18,"narr":"RTO / reverse pickup charges - {description}","active":true,"conds":[["description","regex","RTO CHARGE|RTO FEE|\\yRVP\\y|REVERSE PICKUP|RETURN SHIPPING|REVERSE LOGISTICS"]],"lines":[["debit","Reverse Logistics & RTO Charges","base"],["debit","GST Input Tax Credit (ITC)","tax"],["credit","BANK","amount"]]},{"code":"BNK-COURIER","name":"Courier / freight charges","notes":"Courier services carry 18% GST. The GST part is booked as input tax credit; the rest is expense.","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":10,"stop":true,"auto":true,"gst":18,"narr":"Courier / freight charges - {description}","active":true,"conds":[["description","contains_any","BLUEDART|BLUE DART|DELHIVERY|DTDC|ECOM EXPRESS|XPRESSBEES|SHADOWFAX|EKART|SHIPROCKET|COURIER|FREIGHT|LOGISTICS"]],"lines":[["debit","Freight & Courier Charges - Outward","base"],["debit","GST Input Tax Credit (ITC)","tax"],["credit","BANK","amount"]]},{"code":"BNK-GATEWAY","name":"Payment gateway charges","notes":null,"group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":12,"stop":true,"auto":true,"gst":18,"narr":"Payment gateway charges - {description}","active":true,"conds":[["description","regex","RAZORPAY FEE|RAZORPAY CHG|PAYU FEE|CASHFREE FEE|PAYTM PG|STRIPE FEE|CCAVENUE FEE|\\yMDR\\y|GATEWAY CHARGE"]],"lines":[["debit","Payment Gateway Charges","base"],["debit","GST Input Tax Credit (ITC)","tax"],["credit","BANK","amount"]]},{"code":"BNK-BANK-CHARGES","name":"Bank charges","notes":"Bank service charges attract 18% GST.","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":15,"stop":true,"auto":true,"gst":18,"narr":"Bank charges - {description}","active":true,"conds":[["description","contains_any","BANK CHARGES|BANK-CHARGES|SMS CHARGES|AMC CHARGES|ANNUAL FEE|MIN BAL|NEFT CHG|IMPS CHG|DEBIT CARD FEE|CHEQUE BOOK"]],"lines":[["debit","Bank Charges","base"],["debit","GST Input Tax Credit (ITC)","tax"],["credit","BANK","amount"]]},{"code":"BNK-PENALTY","name":"Marketplace penalties / chargebacks","notes":"Penalties are not a supply - no GST credit. Left for review because a penalty is often disputable (and claimable).","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":20,"stop":true,"auto":false,"gst":null,"narr":"Marketplace penalties / chargebacks - {description}","active":true,"conds":[["description","contains_any","PENALTY|CHARGEBACK|A-TO-Z|ATOZ|SPF DEDUCTION|CANCELLATION FEE|LATE DISPATCH"]],"lines":[["debit","Marketplace Penalties & Chargebacks","base"],["credit","BANK","amount"]]},{"code":"BNK-PACKAGING","name":"Packaging materials","notes":"Posted as a draft for review - purchases usually need a supplier invoice check before ITC is claimed.","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":30,"stop":true,"auto":false,"gst":18,"narr":"Packaging materials - {description}","active":true,"conds":[["description","regex","\\y(PACKAGING|PACKING|CARTON|BUBBLE|POLY ?BAG|TAPE|BOX)"]],"lines":[["debit","Packaging Materials Consumed","base"],["debit","GST Input Tax Credit (ITC)","tax"],["credit","BANK","amount"]]},{"code":"BNK-ADS","name":"Advertising / promotion","notes":"Foreign platforms are billed under reverse charge - the CA may want 0% here and a separate RCM entry.","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":32,"stop":true,"auto":false,"gst":18,"narr":"Advertising / promotion - {description}","active":true,"conds":[["description","contains_any","FACEBOOK|META ADS|GOOGLE ADS|GOOGLEADS|INSTAGRAM|FB ADS|AMAZON ADS|FLIPKART ADS"]],"lines":[["debit","Advertising & Promotion","base"],["debit","GST Input Tax Credit (ITC)","tax"],["credit","BANK","amount"]]},{"code":"BNK-SOFTWARE","name":"Software / subscriptions","notes":null,"group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":34,"stop":true,"auto":false,"gst":18,"narr":"Software / subscriptions - {description}","active":true,"conds":[["description","regex","\\y(SHOPIFY|AWS|AMAZON WEB|GODADDY|VERCEL|SUPABASE|ZOHO|GOOGLE WORKSPACE|MICROSOFT|CANVA|NOTION)\\y"]],"lines":[["debit","Software & Subscriptions","base"],["debit","GST Input Tax Credit (ITC)","tax"],["credit","BANK","amount"]]},{"code":"BNK-PROF-FEES","name":"Professional / audit fees","notes":"TDS under Sec 194J may apply on professional fees - confirm with your CA.","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":36,"stop":true,"auto":false,"gst":18,"narr":"Professional / audit fees - {description}","active":true,"conds":[["description","contains_any","CA FEES|AUDIT FEE|PROFESSIONAL|CONSULTANT|LEGAL FEE|RETAINER"]],"lines":[["debit","Professional & Audit Fees","base"],["debit","GST Input Tax Credit (ITC)","tax"],["credit","BANK","amount"]]},{"code":"BNK-SALARY","name":"Salaries & wages","notes":null,"group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":40,"stop":true,"auto":false,"gst":null,"narr":"Salaries & wages - {description}","active":true,"conds":[["description","contains_any","SALARY|PAYROLL|WAGES|STAFF PAY|STIPEND"]],"lines":[["debit","Salaries & Wages","base"],["credit","BANK","amount"]]},{"code":"BNK-RENT","name":"Rent","notes":"Commercial rent may carry 18% GST and TDS 194-I. Set the GST rate here if your landlord is registered.","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":42,"stop":true,"auto":false,"gst":null,"narr":"Rent - {description}","active":true,"conds":[["description","regex","\\y(RENT|LEASE)\\y"]],"lines":[["debit","Rent","base"],["credit","BANK","amount"]]},{"code":"BNK-UTILITIES","name":"Electricity & utilities","notes":null,"group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":44,"stop":true,"auto":false,"gst":null,"narr":"Electricity & utilities - {description}","active":true,"conds":[["description","contains_any","ELECTRICITY|DGVCL|UGVCL|TORRENT POWER|WATER BILL|BROADBAND|AIRTEL|JIO FIBER|INTERNET"]],"lines":[["debit","Electricity & Utilities","base"],["credit","BANK","amount"]]},{"code":"BNK-ADV-TAX","name":"Advance tax / TDS paid","notes":null,"group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":50,"stop":true,"auto":false,"gst":null,"narr":"Advance tax / TDS paid - {description}","active":true,"conds":[["description","contains_any","ADVANCE TAX|INCOME TAX|TDS PAYMENT|CHALLAN 280|CHALLAN 281|ITNS"]],"lines":[["debit","Advance Tax & TDS Paid","base"],["credit","BANK","amount"]]},{"code":"BNK-GST-PAYMENT","name":"GST paid to government","notes":"Draft for review: the CA splits it between CGST / SGST / IGST ledgers and any interest or late fee.","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":52,"stop":true,"auto":false,"gst":null,"narr":"GST paid - {description}","active":true,"conds":[["description","contains_any","GST PAYMENT|GSTN|CBIC|PMT-06|GST CHALLAN|GST-PMT"]],"lines":[["debit","GST Payable (Output)","amount"],["credit","BANK","amount"]]},{"code":"BNK-FALLBACK-DEBIT","name":"Any other payment - hold in suspense for review","notes":"Catch-all so nothing is silently missed. Accountant reviews and reclassifies.","group":"Bank rules - money out","pack":"core","event":"bank.debit","action":"post","vt":"PAYMENT","mode":"all","priority":900,"stop":true,"auto":false,"gst":null,"narr":"Unclassified payment - {description}","active":true,"conds":[],"lines":[["debit","Suspense - To Be Classified","amount"],["credit","BANK","amount"]]},{"code":"BNK-IGNORE-SETTLEMENT","name":"Marketplace / gateway / courier payouts - leave for reconciliation","notes":"These credits are matched on the Settlements / COD screens, which post the proper entry. Auto-posting them here would double count.","group":"Bank rules - money in","pack":"core","event":"bank.credit","action":"ignore","vt":"JOURNAL","mode":"all","priority":5,"stop":true,"auto":true,"gst":null,"narr":null,"active":true,"conds":[["description","contains_any","AMAZON|AMZN|FLIPKART|SHOPIFY|RAZORPAY|PAYU|CASHFREE|SETTLEMENT|PAYOUT|COD REMIT|COD-REMIT|DELHIVERY COD|BLUEDART COD|DTDC COD"]],"lines":[]},{"code":"BNK-INTEREST","name":"Bank interest received","notes":null,"group":"Bank rules - money in","pack":"core","event":"bank.credit","action":"post","vt":"RECEIPT","mode":"all","priority":10,"stop":true,"auto":true,"gst":null,"narr":"Interest received - {description}","active":true,"conds":[["description","contains_any","INT.PD|INT PD|INTEREST|INT CR|SAVINGS INT"]],"lines":[["debit","BANK","amount"],["credit","Interest Income","amount"]]},{"code":"BNK-UPI-RECEIPT","name":"Customer UPI receipt","notes":"Direct customer payment. Draft for review so the accountant can confirm which invoice it settles.","group":"Bank rules - money in","pack":"core","event":"bank.credit","action":"post","vt":"RECEIPT","mode":"all","priority":20,"stop":true,"auto":false,"gst":null,"narr":"UPI receipt - {description}","active":true,"conds":[["description","starts_with","UPI-CR"]],"lines":[["debit","BANK","amount"],["credit","Trade Receivables","amount"]]},{"code":"BNK-FALLBACK-CREDIT","name":"Any other receipt - hold in suspense for review","notes":null,"group":"Bank rules - money in","pack":"core","event":"bank.credit","action":"post","vt":"RECEIPT","mode":"all","priority":900,"stop":true,"auto":false,"gst":null,"narr":"Unclassified receipt - {description}","active":true,"conds":[],"lines":[["debit","BANK","amount"],["credit","Suspense - To Be Classified","amount"]]}]}$j$::jsonb;
  e jsonb; r jsonb; f jsonb; c jsonb; l jsonb; v uuid; i int; fs text;
begin
  delete from journal_rules where is_system;
  delete from journal_event_fields;
  delete from journal_event_types where event_type not in (select event_type from journal_rules);

  for e in select * from jsonb_array_elements(d -> 'events') loop
    insert into journal_event_types (event_type, label, description, trigger_text, source_type, pack, sample_ctx, sort_order)
    values (e ->> 'code', e ->> 'label', e ->> 'desc', e ->> 'trig', e ->> 'src', e ->> 'pack', e -> 'sample', (e ->> 'order')::int)
    on conflict (event_type) do update set label = excluded.label, description = excluded.description, trigger_text = excluded.trigger_text,
      source_type = excluded.source_type, pack = excluded.pack, sample_ctx = excluded.sample_ctx, sort_order = excluded.sort_order;
    fs := e ->> 'fs';
    if fs is not null then
      for f in select * from jsonb_array_elements(d -> 'fieldsets' -> fs) loop
        insert into journal_event_fields (event_type, field, label, data_type, description)
        values (e ->> 'code', f ->> 0, f ->> 1, f ->> 2, f ->> 3);
      end loop;
    end if;
    for f in select * from jsonb_array_elements(e -> 'extra') loop
      insert into journal_event_fields (event_type, field, label, data_type, description)
      values (e ->> 'code', f ->> 0, f ->> 1, f ->> 2, f ->> 3);
    end loop;
  end loop;

  for r in select * from jsonb_array_elements(d -> 'rules') loop
    insert into journal_rules (rule_code, name, notes, rule_group, pack, event_type, action, voucher_type_code, match_mode, priority,
                               stop_on_match, auto_post, gst_rate_pct, narration_template, effective_from, status, is_system)
    values (r ->> 'code', r ->> 'name', r ->> 'notes', r ->> 'group', r ->> 'pack', r ->> 'event', r ->> 'action', r ->> 'vt', r ->> 'mode',
            (r ->> 'priority')::int, (r ->> 'stop')::boolean, (r ->> 'auto')::boolean, nullif(r ->> 'gst', '')::numeric, r ->> 'narr',
            date '2000-01-01', case when (r ->> 'active')::boolean then 'active' else 'inactive' end, true)
    returning journal_rule_id into v;
    i := 0;
    for c in select * from jsonb_array_elements(r -> 'conds') loop
      i := i + 1;
      insert into journal_rule_conditions (journal_rule_id, sort_order, field, operator, value) values (v, i, c ->> 0, c ->> 1, c ->> 2);
    end loop;
    i := 0;
    for l in select * from jsonb_array_elements(r -> 'lines') loop
      i := i + 1;
      if l ->> 1 = 'BANK' then
        insert into journal_rule_lines (journal_rule_id, sort_order, side, ledger_role, amount_source) values (v, i, l ->> 0, 'bank', l ->> 2);
      else
        if not exists (select 1 from ledgers where name = l ->> 1) then
          raise exception 'Default rule % needs ledger "%" which does not exist - run migration 0049 first', r ->> 'code', l ->> 1;
        end if;
        insert into journal_rule_lines (journal_rule_id, sort_order, side, ledger_id, amount_source)
        values (v, i, l ->> 0, (select ledger_id from ledgers where name = l ->> 1 limit 1), l ->> 2);
      end if;
    end loop;
    perform jr_snapshot_default(v);
  end loop;
end
$seed$;
